"""16x16 button icons (with 32x32 @2x versions for high-DPI).

Usage:
    import button_icons as bi
    btn.SetBitmap(bi.GetBundle("contrast"))
"""
import wx
from wx.lib.embeddedimage import PyEmbeddedImage

_icons = {
	'contrast': (PyEmbeddedImage(b''),
		PyEmbeddedImage(b'')),
	'sharpen': (PyEmbeddedImage(b''),
		PyEmbeddedImage(b'')),
	'edit_info': (PyEmbeddedImage(b''),
		PyEmbeddedImage(b'')),
	'export_view': (PyEmbeddedImage(b''),
		PyEmbeddedImage(b'')),
	'save_photo': (PyEmbeddedImage(b''),
		PyEmbeddedImage(b'')),
}

def GetBitmap(name):
	"""Plain 16x16 wx.Bitmap."""
	return _icons[name][0].GetBitmap()

def GetBundle(name):
	"""wx.BitmapBundle with 16x16 and 32x32 versions; wx picks one to suit the screen."""
	s, d = _icons[name]
	return wx.BitmapBundle.FromBitmaps([s.GetBitmap(), d.GetBitmap()])
